_choice_bundle_config_name() {
    cat <<-'ARGCEOF'
	api_request_size	Configure how many dependencies to fetch when resolving the specifications
	auto_install	Automatically run bundle install when gems are missing
	bin	If configured, bundle binstubs will install executables from gems in the bundle to the specified directory
	cache_all	Cache all gems, including path and git gems
	cache_all_platforms	Cache gems for all platforms
	cache_path	The directory that bundler will place cached gems in when running bundle package, and that bundler will look in when installing gems
	clean	Whether Bundler should run bundle clean automatically after bundle install
	console	The console that bundle console starts
	cooldown	Number of days a published gem version must age before bundler will resolve to it
	default_cli_command	The command that running bundle without arguments should run
	deployment	Equivalent to setting frozen to true and path to vendor/bundle
	disable_checksum_validation	Allow installing gems even if they do not match the checksum provided by RubyGems
	disable_exec_load	Stop Bundler from using load to launch an executable in-process in bundle exec
	disable_local_branch_check	Allow Bundler to use a local git override without a branch specified in the Gemfile
	disable_local_revision_check	Allow Bundler to use a local git override without checking if the revision present in the lockfile is present in the repository
	disable_shared_gems	Stop Bundler from accessing gems installed to RubyGems' normal location
	disable_version_check	Stop Bundler from checking if a newer Bundler version is available on rubygems.org
	force_ruby_platform	Ignore the current machine's platform and install only ruby platform gems
	frozen	Disallow any automatic changes to Gemfile.lock
	gem.github_username	Sets a GitHub username or organization to be used in the README and .gemspec files when you create a new gem via bundle gem command
	gem.push_key	Sets the --key parameter for gem push when using the rake release command with a private gemstash server
	gemfile	The name of the file that bundler should use as the Gemfile
	global_gem_cache	Whether Bundler should cache all gems and compiled extensions globally, rather than locally to the configured installation path
	ignore_funding_requests	When set, no funding requests will be printed
	ignore_messages	When set, no post install messages will be printed
	init_gems_rb	Generate a gems.rb instead of a Gemfile when running bundle init
	jobs	The number of gems Bundler can download and install in parallel
	lockfile	The path to the lockfile that bundler should use
	lockfile_checksums	Whether Bundler should include a checksums section in new lockfiles, to protect from compromised gem sources
	no_install	Whether bundle package should skip installing gems
	no_prune	Whether Bundler should leave outdated gems unpruned when caching
	only	A space-separated list of groups to install only gems of the specified groups
	path	The location on disk where all gems in your bundle will be located regardless of $GEM_HOME or $GEM_PATH values
	path.system	Whether Bundler will install gems into the default system path (Gem.dir)
	plugins	Enable Bundler's experimental plugin system
	prefer_patch	Prefer updating only to next patch version during updates
	redirect	The number of redirects allowed for network requests
	retry	The number of times to retry failed network requests
	shebang	The program name that should be invoked for generated binstubs
	silence_deprecations	Whether Bundler should silence deprecation warnings for behavior that will be changed in the next major version
	silence_root_warning	Silence the warning Bundler prints when installing gems as root
	simulate_version	The virtual version Bundler should use for activating feature flags
	ssl_ca_cert	Path to a designated CA certificate file or folder containing multiple certificates for trusted CAs in PEM format
	ssl_client_cert	Path to a designated file containing a X.509 client certificate and key in PEM format
	ssl_verify_mode	The SSL verification mode Bundler uses when making HTTPS requests
	system_bindir	The location where RubyGems installs binstubs
	timeout	The seconds allowed before timing out for network requests
	update_requires_all_flag	Require passing --all to bundle update when everything should be updated, and disallow passing no options to bundle update
	user_agent	The custom user agent fragment Bundler includes in API requests
	verbose	Whether Bundler should print verbose output
	version	The version of Bundler to use when running under Bundler environment
	with	A space-separated or :-separated list of groups whose gems bundler should install
	without	A space-separated or :-separated list of groups whose gems bundler should not install
ARGCEOF
}

_choice_bundle_gem() {
    local lockfile gems
    lockfile="$(_helper_bundle_lockfile)"
    if [[ -n "$lockfile" && -f "$lockfile" ]]; then
        gems="$(_helper_bundle_lockfile_specs "$lockfile" '^(GEM|PATH|GIT)$')"
        if [[ -n "$gems" ]]; then
            printf '%s\n' "$gems"
            return 0
        fi
    fi
    command gem list --no-versions 2>/dev/null
}

_choice_bundle_group() {
    local gemfile="${argc_gemfile:-}"
    if [[ -z "$gemfile" ]]; then
        gemfile="$(_argc_util_path_search_parent Gemfile)"
    fi
    [[ -n "$gemfile" && -f "$gemfile" ]] || return 0
    gawk '
        /^[[:space:]]*group[[:space:]]/ {
            line = $0
            while (match(line, /:[A-Za-z0-9_]+/)) {
                print substr(line, RSTART + 1, RLENGTH - 1)
                line = substr(line, RSTART + RLENGTH)
            }
        }
    ' "$gemfile"
}

_choice_bundle_platform() {
    local lockfile
    lockfile="$(_helper_bundle_lockfile)"
    [[ -n "$lockfile" && -f "$lockfile" ]] || return 0
    gawk '
        /^PLATFORMS$/ { in_platforms = 1; next }
        /^[^[:space:]]/ { in_platforms = 0 }
        in_platforms && /^  [^[:space:]]/ { print $1 }
    ' "$lockfile"
}

_choice_bundle_plugin() {
    local lockfile plugins
    lockfile="$(_helper_bundle_lockfile)"
    if [[ -n "$lockfile" && -f "$lockfile" ]]; then
        plugins="$(_helper_bundle_lockfile_specs "$lockfile" '^PLUGIN SOURCE$')"
        if [[ -n "$plugins" ]]; then
            printf '%s\n' "$plugins"
            return 0
        fi
    fi
    command bundle plugin list 2>/dev/null | gawk '/^[A-Za-z0-9][A-Za-z0-9_.-]*$/ { print }'
}

_choice_bundle_source() {
    local gemfile="${argc_gemfile:-}"
    if [[ -z "$gemfile" ]]; then
        gemfile="$(_argc_util_path_search_parent Gemfile)"
    fi
    [[ -n "$gemfile" && -f "$gemfile" ]] || return 0
    gawk '
        BEGIN { q = "[\"\047]"; nq = "[^\"\047]" }
        {
            line = $0
            sub(/#.*/, "", line)
            pattern = "(^|[^A-Za-z0-9_])(git|path|github)[[:space:]]*:?[[:space:]]*\\(?" q nq "+" q
            while (match(line, pattern)) {
                value = substr(line, RSTART, RLENGTH)
                sub("^[^" q "]*" q, "", value)
                sub(q "$", "", value)
                sub(/\/+$/, "", value)
                n = split(value, parts, "/")
                name = parts[n]
                sub(/\.git$/, "", name)
                if (name != "" && name != "." && name != "..") print name
                line = substr(line, RSTART + RLENGTH)
            }
        }
    ' "$gemfile"
}

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_helper_bundle_lockfile() {
    local lockfile="${argc_lockfile:-}"
    if [[ -z "$lockfile" ]]; then
        lockfile="$(_argc_util_path_search_parent Gemfile.lock)"
    fi
    printf '%s\n' "$lockfile"
}

_helper_bundle_lockfile_specs() {
    local lockfile="$1" sections="$2"
    [[ -n "$lockfile" && -f "$lockfile" ]] || return 0
    gawk -v sections="$sections" '
        /^[^[:space:]]/ { section = $0; next }
        /^  specs:$/ { in_specs = (section ~ sections); next }
        in_specs && /^    [^[:space:]]/ {
            name = $1
            sub(/ \(.*/, "", name)
            print name
            next
        }
        in_specs && !/^    / { in_specs = 0 }
    ' "$lockfile"
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
